const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata for a file under the workspace data directory.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Path of the file relative to the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const rel = args.path;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }

  // Normalize the requested path and ensure it stays inside DATA_DIR.
  const resolved = path.resolve(DATA_DIR, rel);
  const relFromRoot = path.relative(DATA_DIR, resolved);

  // Reject traversal: resolved path must be within DATA_DIR and not a parent.
  if (relFromRoot === '' || relFromRoot.startsWith('..') || path.isAbsolute(relFromRoot)) {
    throw new Error('Path traversal is not allowed');
  }

  let stat;
  try {
    stat = await fs.stat(resolved);
  } catch (error) {
    throw new Error(`File not found: ${rel}`);
  }

  if (!stat.isFile()) {
    throw new Error(`Not a file: ${rel}`);
  }

  const ext = path.extname(resolved).toLowerCase();
  const text = `path: ${relFromRoot}\nsize: ${stat.size} bytes\nextension: ${ext}`;

  return {
    content: [
      {
        type: 'text',
        text
      }
    ]
  };
}
